fn admit_rows(b:&mut NativeEncodingBound<'_,'_>,rows:&mut usize,add:usize)->Result<(), ValueError>{*rows=rows.checked_add(add).ok_or_else(|| ValueError::new(ValueRefusalKind::WorkLimit, "EN1993 native row count overflow"))?;b.check_rows(*rows)?;b.checkpoint()}
fn admit_strings(b:&mut NativeEncodingBound<'_,'_>,values:&[&str],bytes:usize)->Result<(), ValueError>{b.add(bytes)?;for s in values{b.repeated(s.len(),24)?;}Ok(())}
fn admit_forces(b:&mut NativeEncodingBound<'_,'_>,rows:&mut usize,values:&[ForceAction])->Result<(), ValueError>{admit_rows(b,rows,values.len())?;for a in values{admit_strings(b,&[&a.id,&a.load_case_id],8192)?;}Ok(())}

